    this.halt();
    this.gen = null;
    this.machine = null;
    this.error = null;
    this.line = null;
    this.steps = 0;
    this.state = 'idle';
    this.emit();
  }

  private halt(): void {
    cancelAnimationFrame(this.raf);
    this.raf = 0;
  }
}
EOF

