    this.editor.setValue(b);
    store.saveDraft(this.mode, b);
    if (!this.isPristine(cur)) store.saveBackup(this.mode, cur);
    else store.clearBackup(this.mode);
    this.refresh();
    announce('Przywrócono poprzedni szkic');
  }

