import { chromium } from 'playwright';
import fs from 'fs';
const URL = 'http://localhost:4173/Logomocja/builds/x/';
const b = await chromium.launch({ args: ['--no-sandbox','--use-gl=swiftshader','--enable-unsafe-swiftshader','--ignore-gpu-blocklist'] });
const ctx = await b.newContext({ viewport: { width: 1280, height: 800 }, acceptDownloads: true });
const page = await ctx.newPage();
const logs = [];
page.on('console', m => { if (m.type()==='error'||m.type()==='warning' && !m.text().includes('GPU stall')) logs.push(m.type()+': '+m.text()); });
page.on('pageerror', e => logs.push('PAGEERROR: '+e.message));
await page.goto(URL);
await page.waitForFunction(() => window.logomocja);
const shot = (n) => page.screenshot({ path: `/tmp/pw/out/${n}.png` });
// examples via open
