for (const e of ex) {
  const r = await page.evaluate(([s,m]) => window.logomocja.open(s,m), [e.source, e.mode]);
  console.log(e.id, r.segments.length, r.error);
  await shot('ex-'+e.id);
}
// animated run + step
await page.evaluate(() => window.logomocja.open('np 10', '2d'));
await page.fill('textarea', 'powtorz 4 [\n  np 100\n  pw 90\n]\nnp foo');
await page.click('text=Uruchom');
await page.waitForTimeout(300);
await shot('error');
console.log('status:', await page.textContent('.statusbar'));
console.log('errpanel:', await page.textContent('.error-panel'));
console.log(logs.join('\n'));
await b.close();
EOF
