import { chromium } from 'playwright';
import fs from 'fs';
const URL = 'http://localhost:4173/Logomocja/builds/x/';
const b = await chromium.launch({ args: ['--no-sandbox','--use-gl=swiftshader','--enable-unsafe-swiftshader','--ignore-gpu-blocklist'] });
const ctx = await b.newContext({ viewport: { width: 1280, height: 800 }, acceptDownloads: true, permissions: ['clipboard-read','clipboard-write'] });
const page = await ctx.newPage();
const logs = [];
page.on('console', m => { if ((m.type()==='error'||m.type()==='warning') && !m.text().includes('GPU stall')) logs.push(m.type()+': '+m.text()); });
page.on('pageerror', e => logs.push('PAGEERROR: '+e.message));
await page.goto(URL);
await page.waitForFunction(() => window.logomocja);
const shot = (n) => page.screenshot({ path: `/tmp/pw/out/${n}.png` });
const st = () => page.textContent('.statusbar');

// 1. animated run with slow speed, step, pause
await page.fill('textarea', 'powtorz 4 [\n  np 100\n  pw 90\n]');
await page.locator('#speed').fill('2');
await page.click('button:has-text("Uruchom")');
await page.waitForTimeout(700);
console.log('running:', await st(), '| active bar visible:', await page.locator('.active-bar').isVisible());
await shot('running');
await page.keyboard.press('F8');
console.log('paused:', await st());
await page.keyboard.press('F10');
await page.keyboard.press('F10');
console.log('stepped:', await st());
await page.keyboard.press('F8');
await page.locator('#speed').fill('8');
await page.waitForTimeout(500);
console.log('after resume at instant:', await st());
await page.keyboard.press('Escape');
console.log('reset:', await st());
await page.keyboard.press('Control+Enter');
await page.waitForTimeout(200);
console.log('ctrl+enter:', await st());

// 2. dirty draft + example load
await page.fill('textarea', 'np 77 ; moje');
await page.selectOption('#example-select', 'gwiazda');
await page.waitForSelector('dialog[open]');
await shot('dialog');
await page.click('dialog button:has-text("Anuluj")');
console.log('after cancel:', JSON.stringify(await page.inputValue('textarea')));
await page.selectOption('#example-select', 'gwiazda');
await page.click('dialog button:has-text("Wczytaj i zastąp")');
console.log('after load starts with:', (await page.inputValue('textarea')).slice(0,20));
console.log('restore visible:', await page.locator('button:has-text("Przywróć poprzedni szkic")').isVisible());
await page.click('button:has-text("Przywróć poprzedni szkic")');
console.log('restored:', JSON.stringify(await page.inputValue('textarea')));

// 3. example from 3D into 2D mode switches mode
await page.selectOption('#example-select', 'kula');
console.log('mode 3d checked:', await page.isChecked('#mode-3d'));
await page.click('button:has-text("Uruchom")');
await page.waitForTimeout(500);
await shot('kula-anim');

// 4. permalink
await page.selectOption('#example-select', 'helisa').catch(()=>{});
await page.waitForTimeout(100);
const dlgOpen = await page.locator('dialog[open]').count();
if (dlgOpen) await page.click('dialog button:has-text("Wczytaj i zastąp")');
await page.click('button:has-text("Udostępnij")');
const link = await page.inputValue('dialog input');
console.log('link:', link.slice(0,120), link.length);
await page.click('dialog button:has-text("Zamknij")');
const p2 = await ctx.newPage();
await p2.goto(link);
await p2.waitForTimeout(800);
console.log('permalink status:', await p2.textContent('.statusbar'), '| hash now:', await p2.evaluate(() => location.hash), '| mode3d', await p2.isChecked('#mode-3d'));
await p2.screenshot({ path: '/tmp/pw/out/permalink.png' });

// 5. downloads
const [dl] = await Promise.all([page.waitForEvent('download'), page.click('button:has-text("Pobierz .logo")')]);
console.log('download:', dl.suggestedFilename());
const [png] = await Promise.all([page.waitForEvent('download'), page.click('button:has-text("Zapisz PNG")')]);
await png.saveAs('/tmp/pw/out/export3d.png'); console.log('png:', png.suggestedFilename());
fs.writeFileSync('/tmp/pw/in.logo', 'np 50\npw 90\nnp 50');
await page.setInputFiles('input[type=file]', '/tmp/pw/in.logo');
await page.waitForTimeout(300);
if (await page.locator('dialog[open]').count()) await page.click('dialog button:has-text("Wczytaj i zastąp")');
await page.waitForTimeout(200);
console.log('opened file:', JSON.stringify(await page.inputValue('textarea')), 'mode2d', await page.isChecked('#mode-2d'));

// 6. reload keeps draft
await page.reload();
await page.waitForFunction(() => window.logomocja);
console.log('after reload:', JSON.stringify(await page.inputValue('textarea')));

// 7. 2D png
const [png2] = await Promise.all([page.waitForEvent('download'), page.click('button:has-text("Zapisz PNG")')]);
await png2.saveAs('/tmp/pw/out/export2d.png');

// 8. other pages
for (const r of ['przyklady','wyzwania','instrukcja']) {
  await page.goto(URL + '#/' + r);
  await page.waitForTimeout(500);
  await page.screenshot({ path: `/tmp/pw/out/page-${r}.png` });
}
console.log(logs.join('\n'));
await b.close();
EOF
