cd /tmp/pw && . ./env.sh && cat > t8.mjs <<'EOF'
import { chromium, devices } from 'playwright';
const URL = 'http://localhost:4173/Logomocja/builds/x/';
const b = await chromium.launch({ args: ['--no-sandbox','--use-gl=swiftshader','--enable-unsafe-swiftshader','--ignore-gpu-blocklist'] });
// mobile dark
const ctx = await b.newContext({ ...devices['Pixel 7'], colorScheme: 'dark' });
const page = await ctx.newPage();
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto(URL); await page.waitForFunction(() => window.logomocja);
await page.evaluate(() => window.logomocja.open('powtorz 5 [np 180 pw 144]\n; x', '2d'));
await page.screenshot({ path: '/tmp/pw/out/m-2d-dark.png', fullPage: true });
await page.evaluate(() => window.logomocja.open('grubosc 2\nniech zmiana 1\npowtorz 12 [\n jeżeli zmiana > 0 [kolor "#16866a"] [kolor "#2b6fb3"]\n niech zmiana -zmiana\n powtorz 36 [np 10 gora 10]\n pp 15\n]', '3d'));
await page.screenshot({ path: '/tmp/pw/out/m-3d-dark.png', fullPage: true });
console.log('theme', await page.evaluate(() => document.documentElement.dataset.theme));
await ctx.close();
// no webgl
const b2 = await chromium.launch({ args: ['--no-sandbox','--disable-gpu','--disable-3d-apis','--disable-webgl','--disable-webgl2'] });
const p2 = await (await b2.newContext({ viewport: {width:1100,height:700} })).newPage();
p2.on('pageerror', e => console.log('PAGEERROR2', e.message));
await p2.goto(URL); await p2.waitForFunction(() => window.logomocja);
const r = await p2.evaluate(() => window.logomocja.open('np 100\ngora 90\nnp 50', '3d'));
console.log('no-webgl open', r.segments.length, r.error);
await p2.screenshot({ path: '/tmp/pw/out/nowebgl.png' });
await p2.click('#mode-2d', {force:true});
await p2.waitForTimeout(300);
console.log('2d still works:', (await p2.evaluate(() => window.logomocja.run('np 10','2d'))).segments.length, await p2.textContent('.statusbar'));
await b.close(); await b2.close();
EOF
